mapper.delete:
delete from ${database.prefix.activity}hou_addon_activity_seckill_goods
where 1=1

    and seckill_id = #{param.seckillId,jdbcType=INTEGER}


    and common_id = #{param.commonId,jdbcType=INTEGER}

mapper.select:
SELECT seckill_id, seckill_price, goods_start_time, goods_end_time, goods_upper_limit, seckill_num, (select sum(seckill_num) from ${database.prefix.activity}hou_addon_activity_seckill_goods where seckill_goods_state in(0,1) and common_id = #{param.commonId}) as seckillNums, seckill_goods_state, seckill_name as seckillTitle FROM ${database.prefix.activity}hou_addon_activity_seckill_goods WHERE seckill_goods_state in(0,1)
and goods_start_time = #{param.sessionTime}
and goods_id = #{param.goodsId,jdbcType=INTEGER}
ORDER BY goods_end_time limit 1

SELECT seckill_id, seckill_price, goods_start_time, goods_end_time, goods_upper_limit, seckill_num, seckill_goods_state, seckill_name as seckillTitle FROM ${database.prefix.activity}hou_addon_activity_seckill_goods WHERE seckill_goods_state in(0,1)
and goods_id = #{goodsId,jdbcType=INTEGER}
limit 1

SELECT
sum( order_goods_num )
FROM
${database.prefix.order}hou_order_goods
WHERE
common_id = #{param.commonId}

AND order_goods_time BETWEEN #{param.goodsStartTime} and #{param.goodsEndTime}

AND order_goods_status != 7
AND promotion_id = 2
AND goods_id IN (
SELECT
goods_id
FROM ${database.prefix.activity}hou_addon_activity_seckill_goods
WHERE
seckill_id = #{param.seckillId} and common_id = #{param.commonId}

)

    and buyer_user_id = #{param.userId}


    and goods_promotion_id = #{param.seckillId}

SELECT dg.common_id, dg.goods_id, gc.common_name, gc.common_price, gc.common_image, dg.seckill_price, gc.common_salenum, gc.common_promotion_tips, dg.goods_start_time, dg.goods_end_time, dg.seckill_num, dg.seckill_id, dg.goods_upper_limit, IF( isnull( `gc`.`common_evaluate` ), 0, `gc`.`common_evaluate` ) AS commonEvaluate, dg.seckill_goods_state, sb.shop_name, sb.supplier_shop_id AS shop_id FROM ${database.prefix.activity}hou_addon_activity_seckill_goods dg LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON (gc.common_id = dg.common_id) LEFT JOIN ${database.prefix.business}hou_shop_base sb ON sb.supplier_shop_id = gc.shop_id WHERE gc.common_stock > 0 AND dg.seckill_goods_state in (0,1) AND sb.shop_status = 3 AND gc.common_state = 1 AND gc.common_verify = 1 and gc.common_is_xian = 2 and dg.seckill_num > 0 and dg.goods_start_time = #{param.goodsStartTime}
and gc.shop_id = #{param.shopId}
and gc.goods_type != 3
and common_name LIKE CONCAT('%',#{param.commonName },'%')
GROUP BY dg.common_id ORDER BY dg.goods_start_time desc

SELECT dg.common_id, dg.goods_id, gc.common_name, gc.common_price, gc.common_image, dg.seckill_price, gc.common_salenum, gc.common_promotion_tips, dg.goods_start_time, dg.goods_end_time, dg.seckill_num, dg.goods_upper_limit, IF ( isnull( `gc`.`common_evaluate` ), 0, `gc`.`common_evaluate` ) AS commonEvaluate, dg.seckill_goods_state, sb.shop_name, ROUND(( dg.goods_price - dg.seckill_price )/ dg.goods_price, 3 ) AS proportion, sb.supplier_shop_id AS shop_id FROM ${database.prefix.activity}hou_addon_activity_seckill_goods dg LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON ( gc.common_id = dg.common_id ) LEFT JOIN ${database.prefix.business}hou_shop_base sb ON sb.supplier_shop_id = gc.shop_id WHERE gc.common_stock > 0 AND dg.seckill_goods_state IN ( 0, 1 ) AND sb.shop_status = 3 AND gc.common_state = 1 AND gc.common_verify = 1 AND gc.common_is_xian = 2 AND dg.seckill_num > 0
and gc.shop_id = #{param.shopId}
and gc.goods_type != 3
and dg.goods_id in (
#{goodsId}
)

select dg.seckill_goods_id,dg.goods_id, dg.common_id, dg.shop_id, dg.goods_name, dg.goods_price, dg.seckill_price, gc.goods_image , dg.seckill_id,gc.goods_spec as specValueName from ${database.prefix.activity}hou_addon_activity_seckill_goods dg LEFT JOIN ${database.prefix.goods}hou_goods_base gc ON gc.goods_id = dg.goods_id where 1=1
and dg.seckill_id = #{param.seckillId,jdbcType=INTEGER}
and dg.common_id = #{param.commonId,jdbcType=INTEGER}

select common_id from ${database.prefix.activity}hou_addon_activity_seckill_goods where seckill_goods_state = 1 AND ( now() BETWEEN goods_start_time AND goods_end_time )
and seckill_id != #{seckillId,jdbcType=INTEGER}
and common_id = #{commonId,jdbcType=INTEGER}

select gc.common_id, gc.goods_id, gc.common_name, gc.common_image, gc.common_state,gb.goods_price as common_price,gc.common_is_xian,gc.common_stock from ${database.prefix.goods}hou_goods_common gc left join ${database.prefix.goods}hou_goods_base gb on gb.goods_id=gc.goods_id where gc.shop_status = 3 and gc.common_state = 1 and gc.dealer_goods_flag != 1 and gc.common_verify = 1 and gc.common_is_xian = 0
and gc.shop_id = #{param.shopId,jdbcType=INTEGER}
and gc.virtual_goods = #{param.virtualGoods,jdbcType=INTEGER}
and gc.common_name LIKE CONCAT('%',#{param.commonName },'%')
